(()=>{
 const P=R.platform,X=R.plus,E=R.esc,tr=(az,ru,en)=>({az,ru,en}[R.lang]||az);let editor=null,dirty=false,search='';
 const labels={CT:'KT',MR:'MRT',CR:'Rentgen',US:'USM'};
 const sync=ed=>{if(!ed||!R.$('#pro-editor'))return;document.querySelectorAll('[data-pro-cmd]').forEach(el=>{const k=el.dataset.proCmd,active=['left','center','right','justify'].includes(k)?ed.isActive({textAlign:k}):ed.isActive(k);el.classList.toggle('is-active',active);el.setAttribute('aria-pressed',String(active));});const attrs=ed.getAttributes('textStyle'),values={font:attrs.fontFamily||'Arial',size:attrs.fontSize||'16px',heading:ed.getAttributes('heading').level||'0'};for(const [k,v]of Object.entries(values)){const select=R.$(`[data-pro-select="${k}"]`);if(select)select.value=String(v);}const count=R.$('#pro-word-count');if(count)count.textContent=ed.getText().trim().split(/\s+/).filter(Boolean).length+' '+tr('söz','слов','words');};
 window.addEventListener('radaz-editor-selection',e=>sync(e.detail));
 const b=(label,cmd,attr='')=>`<button type="button" data-pro-cmd="${cmd}" ${attr}>${label}</button>`;
 const draft=()=>{const f=R.$('[data-form="proTemplate"]');if(f){P.draft={...P.draft,...R.formData(f),html:editor?.getHTML()||P.draft.html};}};
 const toolbar=()=>`<div class="pro-toolbar" role="toolbar" aria-label="${tr('Mətn alətləri','Форматирование','Formatting')}"><div>${b('↶','undo','title="Undo"')}${b('↷','redo','title="Redo"')}</div><select data-pro-select="heading" aria-label="${tr('Mətn formatı','Формат','Format')}"><option value="0">${tr('Mətn','Текст','Text')}</option><option value="1">${tr('Başlıq 1','Заголовок 1','Heading 1')}</option><option value="2">${tr('Başlıq 2','Заголовок 2','Heading 2')}</option><option value="3">${tr('Başlıq 3','Заголовок 3','Heading 3')}</option></select><select data-pro-select="font" aria-label="${tr('Şrift','Шрифт','Font')}">${['Arial','Georgia','Times New Roman','Calibri'].map(x=>`<option>${x}</option>`).join('')}</select><select data-pro-select="size" aria-label="${tr('Şrift ölçüsü','Размер','Font size')}">${[12,14,16,18,20,24,28,32].map(x=>`<option value="${x}px" ${x===16?'selected':''}>${x}</option>`).join('')}</select><div>${b('<strong>B</strong>','bold','title="Bold · Ctrl+B"')}${b('<em>I</em>','italic','title="Italic · Ctrl+I"')}${b('<u>U</u>','underline','title="Underline · Ctrl+U"')}${b('<s>S</s>','strike','title="Strikethrough"')}</div><label class="pro-color" title="${tr('Mətn rəngi','Цвет текста','Text color')}">A<input type="color" value="#182e3e" data-pro-select="color" aria-label="${tr('Mətn rəngi','Цвет текста','Text color')}"></label><div>${b('☰','left','title="Align left"')}${b('≡','center','title="Center"')}${b('☷','right','title="Align right"')}${b('☰','justify','title="Justify"')}</div><div>${b('• 1','bulletList','title="Bullet list"')}${b('1. 2.','orderedList','title="Numbered list"')}${b('❝','blockquote','title="Block quote"')}</div><div>${b(tr('Cədvəl','Таблица','Table'),'table')}${b('+ '+tr('sətir','строка','row'),'addRowAfter')}${b('+ '+tr('sütun','столбец','column'),'addColumnAfter')}${b(tr('Birləşdir','Объединить','Merge'),'mergeCells')}${b(tr('Ayır','Разделить','Split'),'splitCell')}${b('− '+tr('sətir','строка','row'),'deleteRow')}${b('− '+tr('sütun','столбец','column'),'deleteColumn')}${b('× '+tr('cədvəl','таблица','table'),'deleteTable')}</div>${b(tr('Formatı təmizlə','Очистить формат','Clear formatting'),'clear')}</div>`;
 X.templatesPage=()=>{if(!R.state.user)return R.authPage(false);const d=P.draft||{},all=X.templates||[],list=all.filter(s=>(P.group==='all'||!P.group||s.modality===P.group)&&s.title.toLocaleLowerCase().includes(search.toLocaleLowerCase()));return P.accountShell(tr('Şablon redaktoru','Редактор шаблонов','Template editor'),`<div class="pro-page-heading"><div><span class="eyebrow">RADAZ · REPORT</span><h1>${tr('Şablon kitabxanası','Библиотека шаблонов','Template library')}</h1></div><button class="btn btn-primary" data-action="proNew">+ ${tr('Yeni şablon','Новый шаблон','New template')}</button></div><div class="pro-template-workspace"><aside class="card pro-library"><label class="field">${tr('Şablon axtar','Поиск шаблона','Find template')}<input id="pro-search" value="${E(search)}" placeholder="${tr('Adına görə axtar','По названию','Search by title')}"></label><nav class="pro-groups">${[['all',tr('Hamısı','Все','All')],...Object.entries(labels)].map(([k,v])=>`<button class="${(P.group||'all')===k?'active':''}" data-action="pGroup" data-group="${k}">${v}<span>${all.filter(s=>k==='all'||s.modality===k).length}</span></button>`).join('')}</nav><div class="pro-template-list">${list.map(s=>`<button class="${d.id===s.id?'active':''}" data-action="pEditTemplate" data-id="${E(s.id)}"><span>${labels[s.modality]} · ${E(s.lang.toUpperCase())}</span><strong>${E(s.title)}</strong></button>`).join('')||`<p class="a-empty">${tr('Şablon tapılmadı.','Шаблоны не найдены.','No templates found.')}</p>`}</div></aside><section class="card pro-editor-card"><form data-form="proTemplate"><div class="pro-editor-meta"><label class="field">${tr('Şablonun adı','Название шаблона','Template title')}<input name="title" value="${E(d.title||'')}" required maxlength="150"></label><label class="field">${tr('Müayinə qrupu','Группа','Modality')}<select name="modality">${Object.entries(labels).map(([k,v])=>`<option value="${k}" ${d.modality===k?'selected':''}>${v}</option>`).join('')}</select></label><label class="field">${R.t('Dil')}<select name="lang">${[['az','AZ'],['ru','RU'],['en','EN']].map(([k,v])=>`<option value="${k}" ${d.lang===k?'selected':''}>${v}</option>`).join('')}</select></label></div>${toolbar()}<div class="pro-paper"><div id="pro-editor"></div></div><div class="pro-editor-status"><span id="pro-draft-state">${dirty?tr('Saxlanmamış dəyişikliklər','Несохранённые изменения','Unsaved changes'):tr('Redaktəyə hazırdır','Готово к редактированию','Ready to edit')}</span><span id="pro-word-count"></span></div><div class="pro-editor-footer"><button class="btn btn-primary" type="submit">${tr('Şablonu saxla','Сохранить шаблон','Save template')}</button><button type="button" class="btn btn-outline" data-action="proPreview">${tr('Önbaxış','Просмотр','Preview')}</button>${d.id?`<button type="button" class="btn btn-outline" data-action="proDuplicate">${tr('Surətini yarat','Создать копию','Duplicate')}</button><button type="button" class="btn btn-outline" data-action="proDelete" data-id="${E(d.id)}">${R.t('Sil')}</button>`:''}<small>Ctrl + S</small></div></form></section></div>`);};
 const mount=()=>{editor?.destroy();editor=null;const target=R.$('#pro-editor');if(!target)return;editor=RADAZEditor.mount(target,P.draft.html,(html,text)=>{P.draft.html=html;dirty=true;R.$('#pro-draft-state').textContent=tr('Saxlanmamış dəyişikliklər','Несохранённые изменения','Unsaved changes');R.$('#pro-word-count').textContent=text.trim().split(/\s+/).filter(Boolean).length+' '+tr('söz','слов','words');});};
 R.actions.proNew=()=>{draft();dirty=false;P.draft={title:'',modality:P.group==='all'?'CT':P.group||'CT',lang:R.lang,html:'<h2>Müayinə</h2><p></p><h2>Tapıntılar</h2><p></p><h2>Nəticə</h2><p></p>'};R.render();};
 R.actions.pNewTemplate=R.actions.proNew;
 R.actions.pGroup=el=>{draft();P.group=el.dataset.group;R.render();};
 R.actions.pEditTemplate=el=>{draft();const t=X.templates.find(t=>t.id===el.dataset.id);if(t){P.draft={...t};dirty=false;R.render();}};
 R.actions.proDuplicate=()=>{draft();P.draft={...P.draft,id:undefined,title:P.draft.title+' — '+tr('surət','копия','copy')};dirty=true;R.render();};
 R.actions.proPreview=()=>{draft();R.modal(tr('Şablona önbaxış','Просмотр шаблона','Template preview'),`<article class="pro-document"><h1>${E(P.draft.title)}</h1>${R.safeHTML(P.draft.html)}</article>`,true);};
 R.actions.proDelete=el=>R.modal(tr('Şablonu sil','Удалить шаблон','Delete template'),`<p>${tr('Bu şablonu silmək istəyirsiniz?','Удалить этот шаблон?','Delete this template?')}</p><button class="btn btn-primary" data-action="proDeleteConfirm" data-id="${E(el.dataset.id)}">${R.t('Sil')}</button>`);
 R.actions.proDeleteConfirm=async el=>{await R.request('/x/templates/'+encodeURIComponent(el.dataset.id),{method:'DELETE',body:{}});X.templates=await X.req('/templates');R.closeModal();R.actions.proNew();};
 R.forms.proTemplate=async()=>{draft();if(!editor?.getText().trim())throw Error(tr('Şablon mətni boşdur.','Шаблон пуст.','Template text is empty.'));const d=P.draft,r=await R.request('/x/templates'+(d.id?'/'+encodeURIComponent(d.id):''),{method:d.id?'PUT':'POST',body:d});P.draft={...r};dirty=false;X.templates=await X.req('/templates');R.render();R.toast(tr('Şablon saxlanıldı.','Шаблон сохранён.','Template saved.'));};
 document.addEventListener('mousedown',e=>{if(e.target.closest('[data-pro-cmd]'))e.preventDefault();});
 document.addEventListener('input',e=>{if(e.target.matches('[data-form="proTemplate"] input[name]')){draft();dirty=true;R.$('#pro-draft-state').textContent=tr('Saxlanmamış dəyişikliklər','Несохранённые изменения','Unsaved changes');}});
 document.addEventListener('click',e=>{const cmd=e.target.closest('[data-pro-cmd]')?.dataset.proCmd;if(!cmd||!editor)return;let chain=editor.chain().focus();if(['bold','italic','underline','strike','bulletList','orderedList','blockquote'].includes(cmd))chain['toggle'+cmd[0].toUpperCase()+cmd.slice(1)]().run();else if(['left','center','right','justify'].includes(cmd))chain.setTextAlign(cmd).run();else if(cmd==='table')chain.insertTable({rows:3,cols:3,withHeaderRow:true}).run();else if(cmd==='clear')chain.unsetAllMarks().clearNodes().run();else if(typeof chain[cmd]==='function')chain[cmd]().run();});
 document.addEventListener('change',e=>{const k=e.target.dataset.proSelect;if(k&&editor){const c=editor.chain().focus(),v=e.target.value;if(k==='heading')Number(v)?c.toggleHeading({level:Number(v)}).run():c.setParagraph().run();if(k==='font')c.setFontFamily(v).run();if(k==='size')c.setFontSize(v).run();if(k==='color')c.setColor(v).run();}if(e.target.id==='pro-search'){draft();search=e.target.value;R.render();}if(e.target.closest('[data-form="proTemplate"]')&&!k){draft();dirty=true;}});
 document.addEventListener('keydown',e=>{if(R.state.route==='/templates'&&(e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='s'){e.preventDefault();R.$('[data-form="proTemplate"]')?.requestSubmit();}});
 window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});
 for(const key of ['login','logout','register']){const fn=R.api[key];R.api[key]=async(...a)=>{dirty=false;search='';editor?.destroy();editor=null;return fn(...a);};}
 const render=R.render;R.render=()=>{render();mount();sync(editor);};
})();
